INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63504820', 63504820, 'analyze_legacy', 'Kementerian Perumahan dan Kawasan Permukiman', 'central', '05 Perumahan dan Kawasan Permukiman Provinsi Jambi', 'MK Pembangunan Rumah Susun MA RI Jambi', 'Jasa Konsultansi', 'Pembayaran untuk Kontrak Tahun Jamak', '', 500240000, 'October 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Belanja Modal Gedung dan Bangunan;', 'Pekerjaan Manajemen Konstruksi meliputi pengendalian waktu, biaya, pencapaian sasaran fisik (kuantitas dan kualitas), dan tertib administrasi di dalam Pembangunan Rumah Susun Mahkamah Agung RI Jambi. Keluaran Kegiatan ini akan menghasilkan keluaran yang lengkap sesuai kebutuhan proyek kelancaran proyek yang berhubungan dengan Manajemen Konstruksi. Selain hal tersebut, hasil dari pelaksanaan kegiatan Manajemen Konstruksi pembangunan rumah susun adalah dokumen pelaporan seperti : 1. Laporan RKK Konsultansi Konstruksi Manajemen Penyelenggaraan Konstruksi; 2. Laporan Program Mutu Konsultansi Konstruksi Manajemen Penyelenggaraan Konstruksi; 3. Laporan Pendahuluan Konsultansi Konstruksi Manajemen Penyelenggaraan Konstruksi; 4. Laporan Akhir Konsultansi Konstruksi Manajemen Penyelenggaraan Konstruksi; 5. Laporan Bulanan; 6. Pemeriksaan dan/atau Persetujuan Laporan Kemajuan Pekerjaan; 7. Justifikasi Teknis Perubahan/Penyesuaian Pekerjaan (jika ada); 8. Pemeriksaan dan/atau Persetujuan Shop Drawing dan As-Built Drawing; 9. Pemeriksaan dan/atau Persetujuan dokumen lain yang dibutuhkan selama pengawasan seperti Approval Material, Berita Acara Pemeriksaan Pekerjaan (BAPP), Berita Acara Kemajuan Pekerjaan (BAKP), dan Berita Acara Serah Terima Pekerjaan/Provisional Hand Over (PHO), Berita Acara Serah Terima Akhir Pekerjaan/Final Hand Over (FHO). Semua laporan baik dalam bentuk hard copy maupun dalam bentuk soft copy dari kegiatan ini menjadi hak milik Balai Pelaksana Penyediaan Perumahan dan Kawasan Permukiman Sumatera IV / Satker Perumahan dan Kawasan Permukiman Provinsi Jambi, Direktorat Jenderal Perumahan Perkotaan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 0, 967570);
